import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';

interface Result {
  text: string;
  sentiment: 'positif' | 'neutre' | 'negatif';
  emoji: string;
  confidence: number;
}

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './app.component.html',
  styleUrl: './app.component.css',
})
export class AppComponent {
  private apiUrl = 'http://localhost:3001/api/classify';

  inputText = '';
  results: Result[] = [];
  loading = false;
  errorMsg = '';

  submit() {
    const lines = this.inputText
      .split('\n')
      .map((l) => l.trim())
      .filter((l) => l.length > 0);

    if (lines.length === 0) {
      this.errorMsg = 'Colle au moins un avis (une ligne = un avis).';
      return;
    }

    this.errorMsg = '';
    this.results = [];
    this.loading = true;

    this.http.post<{ results: Result[] }>(this.apiUrl, { texts: lines }).subscribe({
      next: (res) => {
        this.results = res.results;
        this.loading = false;
      },
      error: (err) => {
        this.errorMsg = err?.error?.error || 'Erreur de connexion au serveur.';
        this.loading = false;
      },
    });
  }

  constructor(private http: HttpClient) {}
}
<div class="container">
  <h1>💬 Analyseur de sentiment</h1>
  <p class="subtitle">Colle une liste d'avis clients ou de tickets (un par ligne), l'IA les classe automatiquement.</p>

  <textarea
    [(ngModel)]="inputText"
    rows="8"
    placeholder="Un avis par ligne, par exemple :&#10;Le service était rapide et efficace, très satisfait&#10;Livraison en retard de 3 jours, aucune excuse&#10;Le produit correspond a la description"
  ></textarea>

  <button class="submit-btn" (click)="submit()" [disabled]="loading">
    {{ loading ? 'Analyse en cours...' : 'Analyser' }}
  </button>

  <p class="hint" *ngIf="loading">Premier appel un peu plus lent (le modèle se charge) — patiente 20-30s si besoin.</p>
  <p class="error" *ngIf="errorMsg">{{ errorMsg }}</p>

  <div class="results" *ngIf="results.length">
    <div class="result-row" *ngFor="let r of results" [ngClass]="r.sentiment">
      <span class="emoji">{{ r.emoji }}</span>
      <span class="text">{{ r.text }}</span>
      <span class="badge">{{ r.sentiment }} · {{ r.confidence }}%</span>
    </div>
  </div>
</div>
